 19	type testAPI struct {
 20		t     *testing.T
 21		srv   *Server
 22		clk   *clock.Fake
 23		hooks *webhook.Dispatcher
 24	}
 25	
 26	type okSender struct{}
 27	
 28	func (okSender) Send(_ context.Context, _ webhook.Delivery) (int, error) { return http.StatusOK, nil }
 29	
 30	func newTestAPI(t *testing.T) *testAPI {
 31		clk := clock.NewFake(time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC))
 32		hooks := webhook.NewDispatcher(okSender{}, webhook.StaticEndpoints{}, clk, webhook.DefaultPolicy())
 33		svc := payment.NewService(store.NewMemory(), clk, payment.NewSeqIDs(), hooks, payment.Config{FeeBps: 290})
 34		return &testAPI{t: t, srv: NewServer(svc, idempotency.NewMemory(clk, 24*time.Hour), hooks), clk: clk, hooks: hooks}
 35	}
 36	
 37	func (a *testAPI) do(method, path, body string, headers ...string) *httptest.ResponseRecorder {
 38		a.t.Helper()
 39		req := httptest.NewRequest(method, path, bytes.NewBufferString(body))
 40		for i := 0; i+1 < len(headers); i += 2 {
 41			req.Header.Set(headers[i], headers[i+1])
 42		}
 43		rec := httptest.NewRecorder()
 44		a.srv.ServeHTTP(rec, req)
 45		return rec
 46	}
 47	
 48	func decode[T any](t *testing.T, rec *httptest.ResponseRecorder) T {
 49		t.Helper()
 50		var v T
 51		if err := json.Unmarshal(rec.Body.Bytes(), &v); err != nil {
 52			t.Fatalf("decode %q: %v", rec.Body.String(), err)
 53		}
 54		return v
 55	}
 56	
 57	func (a *testAPI) createSucceeded(amount, currency string) paymentResponse {
 58		a.t.Helper()
 59		rec := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"`+amount+`","currency":"`+currency+`"}`)
 60		if rec.Code != http.StatusCreated {
 61			a.t.Fatalf("create: %d %s", rec.Code, rec.Body)
 62		}
 63		p := decode[paymentResponse](a.t, rec)
 64		for _, step := range []string{"authorize", "capture"} {
 65			if rec := a.do("POST", "/payments/"+p.ID+"/"+step, ""); rec.Code != http.StatusOK {
 66				a.t.Fatalf("%s: %d %s", step, rec.Code, rec.Body)
 67			}
 68		}
 69		return decode[paymentResponse](a.t, a.do("GET", "/payments/"+p.ID, ""))
 70	}
