 72	func TestCreatePayment(t *testing.T) {
 73		a := newTestAPI(t)
 74		rec := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"100.00","currency":"USD"}`)
 75		if rec.Code != http.StatusCreated {
 76			t.Fatalf("status %d: %s", rec.Code, rec.Body)
 77		}
 78		p := decode[paymentResponse](t, rec)
 79		if p.Status != "CREATED" || p.Amount != "100.00" || p.Currency != "USD" || p.Fee != "2.90" || p.RemainingAmount != "100.00" {
 80			t.Fatalf("unexpected payment %+v", p)
 81		}
 82	}
