 84	func TestCreatePaymentValidation(t *testing.T) {
 85		tests := []struct {
 86			name, body string
 87		}{
 88			{"malformed", `{`},
 89			{"unknown field", `{"merchant_id":"m","amount":"1","currency":"USD","x":1}`},
 90			{"bad amount", `{"merchant_id":"m","amount":"1.234","currency":"USD"}`},
 91			{"bad currency", `{"merchant_id":"m","amount":"1","currency":"ZZZ"}`},
 92			{"missing merchant", `{"amount":"1","currency":"USD"}`},
 93			{"zero", `{"merchant_id":"m","amount":"0","currency":"USD"}`},
 94		}
 95		for _, tt := range tests {
 96			t.Run(tt.name, func(t *testing.T) {
 97				a := newTestAPI(t)
 98				rec := a.do("POST", "/payments", tt.body)
 99				if rec.Code != http.StatusBadRequest {
100					t.Fatalf("status %d: %s", rec.Code, rec.Body)
101				}
102				if e := decode[errorBody](t, rec); e.Error.Code != "invalid_request" {
103					t.Fatalf("code %q", e.Error.Code)
104				}
105			})
106		}
107	}
