109	func TestLifecycleAndRefund(t *testing.T) {
110		a := newTestAPI(t)
111		p := a.createSucceeded("50.00", "USD")
112		if p.Status != "SUCCEEDED" {
113			t.Fatalf("status %s", p.Status)
