// List returns one page of a merchant's payments.
func (s *Service) List(ctx context.Context, merchantID string, page Page) ([]Payment, string, error) {
	if merchantID == "" {
		return nil, "", fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
	}
	if page.Status != "" {
		st, err := ParseStatus(string(page.Status))
		if err != nil {
			return nil, "", fmt.Errorf("list payments of %s: %w", merchantID, err)
		}
		page.Status = st
	}
	ps, next, err := s.repo.ListByMerchant(ctx, merchantID, page)
	if err != nil {
		return nil, "", fmt.Errorf("list payments of %s: %w", merchantID, err)
	}
	return ps, next, nil
}

// ListByMerchant pages through a merchant's payments in creation order.
func (m *Memory) ListByMerchant(_ context.Context, merchantID string, page payment.Page) ([]payment.Payment, string, error) {
	limit := page.Limit
	switch {
	case limit < 0:
		return nil, "", fmt.Errorf("%w: limit must not be negative", payment.ErrInvalidInput)
	case limit == 0:
		limit = defaultLimit
	case limit > maxLimit:
		limit = maxLimit
	}
	var status payment.Status
	if page.Status != "" {
		var err error
		if status, err = payment.ParseStatus(string(page.Status)); err != nil {
			return nil, "", err
		}
	}
	offset := 0
	if page.Cursor != "" {
		var err error
		if offset, err = decodeCursor(page.Cursor); err != nil {
			return nil, "", err
		}
	}

	m.mu.RLock()
	defer m.mu.RUnlock()
	ids := m.byMerchant[merchantID]
	if offset > len(ids) {
		offset = len(ids)
	}
	out := make([]payment.Payment, 0, min(limit, len(ids)-offset))
	nextOffset := -1
	for i := offset; i < len(ids); i++ {
		p := m.byID[ids[i]]
		if status != "" && p.Status != status {
			continue
		}
		if len(out) < limit {
			out = append(out, p.Clone())
			continue
		}
		nextOffset = i
		break
	}
	next := ""
	if nextOffset >= 0 {
		next = encodeCursor(nextOffset)
	}
	return out, next, nil
}

