func TestListFilterByStatusAndPagination(t *testing.T) {
	ctx := context.Background()
	m := NewMemory()
	statuses := []payment.Status{
		payment.StatusCreated,   // 0
		payment.StatusSucceeded, // 1
		payment.StatusDeclined,  // 2
		payment.StatusSucceeded, // 3
		payment.StatusPending,   // 4
		payment.StatusSucceeded, // 5
		payment.StatusRefunded,  // 6
		payment.StatusSucceeded, // 7
		payment.StatusDeclined,  // 8 (trailing non-match)
		payment.StatusCreated,   // 9 (trailing non-match)
	}
	var wantSucceeded []string
	for i, st := range statuses {
		id := fmt.Sprintf("m1_pay_%03d", i)
		p := payment.Payment{ID: id, MerchantID: "m1", Amount: money.MustNew(100, "USD"), Status: st, Version: 1}
		if err := m.Create(ctx, p); err != nil {
			t.Fatal(err)
		}
		if st == payment.StatusSucceeded {
			wantSucceeded = append(wantSucceeded, id)
		}
	}
	// Other merchant's succeeded payment must not appear.
	if err := m.Create(ctx, payment.Payment{ID: "m2_pay_000", MerchantID: "m2", Amount: money.MustNew(100, "USD"), Status: payment.StatusSucceeded, Version: 1}); err != nil {
		t.Fatal(err)
	}

	for _, limit := range []int{1, 2, 3, 4, 10} {
		var seen []string
		cursor := ""
		pages := 0
		for {
			got, next, err := m.ListByMerchant(ctx, "m1", payment.Page{Cursor: cursor, Limit: limit, Status: payment.StatusSucceeded})
			if err != nil {
				t.Fatalf("limit %d: %v", limit, err)
			}
			pages++
			if next != "" && len(got) != limit {
				t.Fatalf("limit %d page %d: non-final page has %d items, want %d", limit, pages, len(got), limit)
			}
			for _, p := range got {
				if p.Status != payment.StatusSucceeded {
					t.Fatalf("unexpected status %s", p.Status)
				}
				seen = append(seen, p.ID)
			}
			if next == "" {
				break
			}
			cursor = next
			if pages > 20 {
				t.Fatalf("limit %d: infinite cursor loop", limit)
			}
		}
		if fmt.Sprint(seen) != fmt.Sprint(wantSucceeded) {
			t.Fatalf("limit %d: seen %v, want %v", limit, seen, wantSucceeded)
		}
	}

	// Zero matches returns empty slice and empty cursor.
	got, next, err := m.ListByMerchant(ctx, "m2", payment.Page{Limit: 2, Status: payment.StatusDeclined})
	if err != nil || len(got) != 0 || next != "" {
		t.Fatalf("zero matches: got %v next %q err %v", got, next, err)
	}
}

