func TestListStatusValidation(t *testing.T) {
	repo := newFakeRepo()
	s := NewService(repo, clock.NewFake(time.Now()), NewSeqIDs(), nil, Config{})
	ctx := context.Background()

	if _, _, err := s.List(ctx, "", Page{}); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("empty merchant: %v", err)
	}
	if _, _, err := s.List(ctx, "m1", Page{Status: "VOIDED"}); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("unknown status: %v", err)
	}
	if _, _, err := s.List(ctx, "m1", Page{Status: "succeeded", Limit: 5}); err != nil {
		t.Fatalf("valid status: %v", err)
	}
	if repo.lastPage.Status != StatusSucceeded || repo.lastPage.Limit != 5 {
		t.Fatalf("repo got page %+v", repo.lastPage)
	}
}

