func TestListPaymentsFilterByStatus(t *testing.T) {
	a := newTestAPI(t)

	create := func(merchant string) string {
		rec := a.do("POST", "/payments", `{"merchant_id":"`+merchant+`","amount":"10.00","currency":"USD"}`)
		if rec.Code != http.StatusCreated {
			t.Fatalf("create: %d %s", rec.Code, rec.Body)
		}
		return decode[paymentResponse](t, rec).ID
	}

	p0 := create("m_1") // stays CREATED
	p1 := create("m_1") // will become SUCCEEDED (captured out of order)
	p2 := create("m_1") // DECLINED
	p3 := create("m_1") // SUCCEEDED (partially refunded, stays SUCCEEDED)
	p4 := create("m_1") // PENDING
	p5 := create("m_1") // REFUNDED (fully refunded)
	p6 := create("m_1") // SUCCEEDED
	p7 := create("m_1") // DECLINED (trailing non-match for succeeded)
	other := create("m_2")

	// Transition out of creation order to verify creation order is preserved.
	for _, id := range []string{p6, p5, p4, p3, p1, other} {
		if rec := a.do("POST", "/payments/"+id+"/authorize", ""); rec.Code != http.StatusOK {
			t.Fatalf("authorize %s: %d", id, rec.Code)
		}
	}
	for _, id := range []string{p6, p5, p3, p1, other} {
		if rec := a.do("POST", "/payments/"+id+"/capture", ""); rec.Code != http.StatusOK {
			t.Fatalf("capture %s: %d", id, rec.Code)
		}
	}
	for _, id := range []string{p2, p7} {
		if rec := a.do("POST", "/payments/"+id+"/decline", `{"reason":"fraud"}`); rec.Code != http.StatusOK {
			t.Fatalf("decline %s: %d", id, rec.Code)
		}
	}
	if rec := a.do("POST", "/payments/"+p3+"/refunds", `{"amount":"3.00"}`); rec.Code != http.StatusCreated {
		t.Fatalf("partial refund: %d", rec.Code)
	}
	if rec := a.do("POST", "/payments/"+p5+"/refunds", `{"amount":"10.00"}`); rec.Code != http.StatusCreated {
		t.Fatalf("full refund: %d", rec.Code)
	}

	// Paginate succeeded (case-insensitive) with limit=2: 3 matches [p1, p3, p6].
	var gotSucceeded []string
	cursor := ""
	for pageNum := 0; ; pageNum++ {
		path := "/merchants/m_1/payments?status=succeeded&limit=2"
		if cursor != "" {
			path += "&cursor=" + cursor
		}
		rec := a.do("GET", path, "")
		if rec.Code != http.StatusOK {
			t.Fatalf("status %d: %s", rec.Code, rec.Body)
		}
		res := decode[listResponse](t, rec)
		if res.NextCursor != "" && len(res.Data) != 2 {
			t.Fatalf("page %d: got %d items with next_cursor=%q", pageNum, len(res.Data), res.NextCursor)
		}
		for _, p := range res.Data {
			if p.Status != "SUCCEEDED" {
				t.Fatalf("got status %s", p.Status)
			}
			gotSucceeded = append(gotSucceeded, p.ID)
		}
		if res.NextCursor == "" {
			break
		}
		cursor = res.NextCursor
	}
	wantSucceeded := []string{p1, p3, p6}
	if len(gotSucceeded) != len(wantSucceeded) || gotSucceeded[0] != p1 || gotSucceeded[1] != p3 || gotSucceeded[2] != p6 {
		t.Fatalf("succeeded = %v, want %v", gotSucceeded, wantSucceeded)
	}

	// Exact page multiple: 2 DECLINED [p2, p7] with limit=2 must have empty next_cursor on page 1.
	rec := a.do("GET", "/merchants/m_1/payments?status=DeClInEd&limit=2", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("declined status %d", rec.Code)
	}
	decPage := decode[listResponse](t, rec)
	if len(decPage.Data) != 2 || decPage.Data[0].ID != p2 || decPage.Data[1].ID != p7 || decPage.NextCursor != "" {
		t.Fatalf("declined page = %+v", decPage)
	}

	// Check CREATED, PENDING, REFUNDED filters.
	for _, tc := range []struct {
		q, wantID string
	}{
		{"CREATED", p0},
		{"pending", p4},
		{"Refunded", p5},
	} {
		rec := a.do("GET", "/merchants/m_1/payments?status="+tc.q, "")
		if rec.Code != http.StatusOK {
			t.Fatalf("%s: %d", tc.q, rec.Code)
		}
		res := decode[listResponse](t, rec)
		if len(res.Data) != 1 || res.Data[0].ID != tc.wantID || res.NextCursor != "" {
			t.Fatalf("%s: got %+v", tc.q, res)
		}
	}

	// Without status behaves as today: all 8 payments of m_1 in creation order.
	rec = a.do("GET", "/merchants/m_1/payments?limit=20", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("unfiltered: %d", rec.Code)
	}
	all := decode[listResponse](t, rec)
	if len(all.Data) != 8 || all.NextCursor != "" {
		t.Fatalf("unfiltered count=%d next=%q", len(all.Data), all.NextCursor)
	}

	// Unknown status returns 400 invalid_request.
	for _, bad := range []string{"unknown", "VOIDED", "paid", ""} {
		rec := a.do("GET", "/merchants/m_1/payments?status="+bad, "")
		if rec.Code != http.StatusBadRequest {
			t.Fatalf("status=%q: got %d, want 400 (%s)", bad, rec.Code, rec.Body)
		}
		if e := decode[errorBody](t, rec); e.Error.Code != "invalid_request" {
			t.Fatalf("status=%q: code %q, want invalid_request", bad, e.Error.Code)
		}
	}
}

