118	// Authorize moves a CREATED payment to PENDING (sent to the provider).
119	func (s *Service) Authorize(ctx context.Context, id string) (Payment, error) {
120		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
121			switch p.Status {
122			case StatusCreated:
123				p.Status = StatusPending
124				return Event{Type: "payment.pending"}, nil
125			default:
126				return Event{}, fmt.Errorf("%w: cannot authorize a %s payment", ErrInvalidTransition, p.Status)
127			}
128		})
129	}
130	
131	// Capture moves a PENDING payment to SUCCEEDED.
132	func (s *Service) Capture(ctx context.Context, id string) (Payment, error) {
133		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
134			switch p.Status {
135			case StatusPending:
136				p.Status = StatusSucceeded
137				return Event{Type: "payment.succeeded"}, nil
138			default:
139				return Event{}, fmt.Errorf("%w: cannot capture a %s payment", ErrInvalidTransition, p.Status)
140			}
141		})
142	}
