144	// Decline moves a CREATED or PENDING payment to DECLINED.
145	func (s *Service) Decline(ctx context.Context, id, reason string) (Payment, error) {
146		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
147			switch p.Status {
148			case StatusCreated, StatusPending:
149				p.Status = StatusDeclined
150				p.DeclineReason = reason
151				return Event{Type: "payment.declined"}, nil
152			default:
153				return Event{}, fmt.Errorf("%w: cannot decline a %s payment", ErrInvalidTransition, p.Status)
154			}
155		})
156	}
