158	// Refund refunds amount of a SUCCEEDED payment. Partial refunds keep the
159	// payment SUCCEEDED; once the whole amount is refunded it becomes REFUNDED.
160	func (s *Service) Refund(ctx context.Context, id string, amount money.Amount) (Payment, Refund, error) {
161		if !amount.IsPositive() {
162			return Payment{}, Refund{}, fmt.Errorf("%w: refund amount must be positive, got %s", ErrInvalidInput, amount)
163		}
164		var refund Refund
165		p, err := s.mutate(ctx, id, func(p *Payment) (Event, error) {
166			switch p.Status {
167			case StatusSucceeded:
168			default:
169				return Event{}, fmt.Errorf("%w: cannot refund a %s payment", ErrInvalidTransition, p.Status)
170			}
171			if amount.Currency != p.Amount.Currency {
172				return Event{}, fmt.Errorf("%w: refund in %s for a %s payment", money.ErrCurrencyMismatch, amount.Currency.Code, p.Amount.Currency.Code)
173			}
174			if amount.Minor > p.Remaining().Minor {
175				return Event{}, fmt.Errorf("%w: requested %s, remaining %s", ErrRefundExceedsRemaining, amount, p.Remaining())
176			}
177			refund = Refund{ID: s.ids.NewID("ref"), Amount: amount, CreatedAt: s.clock.Now()}
178			p.Refunded += amount.Minor
179			p.Refunds = append(p.Refunds, refund)
180			evType := "payment.partially_refunded"
181			if p.Refunded == p.Amount.Minor {
182				p.Status = StatusRefunded
183				evType = "payment.refunded"
184			}
185			return Event{Type: evType, Refund: &refund}, nil
186		})
187		if err != nil {
188			return Payment{}, Refund{}, err
189		}
190		return p, refund, nil
191	}
