193	// mutate loads a payment, applies change and saves it with optimistic locking.
194	func (s *Service) mutate(ctx context.Context, id string, change func(p *Payment) (Event, error)) (Payment, error) {
195		p, err := s.repo.Get(ctx, id)
196		if err != nil {
197			return Payment{}, fmt.Errorf("load payment %s: %w", id, err)
198		}
199		ev, err := change(&p)
200		if err != nil {
201			return Payment{}, fmt.Errorf("payment %s: %w", id, err)
202		}
203		p.UpdatedAt = s.clock.Now()
204		if err := s.repo.Update(ctx, p); err != nil {
205			return Payment{}, fmt.Errorf("save payment %s: %w", id, err)
206		}
207		p.Version++
208		ev.Payment = p
209		s.publish(ctx, ev)
210		return p, nil
211	}
