 77	// ListByMerchant pages through a merchant's payments in creation order.
 78	func (m *Memory) ListByMerchant(_ context.Context, merchantID string, page payment.Page) ([]payment.Payment, string, error) {
 79		limit := page.Limit
 80		switch {
 81		case limit < 0:
 82			return nil, "", fmt.Errorf("%w: limit must not be negative", payment.ErrInvalidInput)
 83		case limit == 0:
 84			limit = defaultLimit
 85		case limit > maxLimit:
 86			limit = maxLimit
 87		}
 88		var status payment.Status
 89		if page.Status != "" {
 90			var err error
 91			if status, err = payment.ParseStatus(string(page.Status)); err != nil {
 92				return nil, "", err
 93			}
 94		}
 95		offset := 0
 96		if page.Cursor != "" {
 97			var err error
 98			if offset, err = decodeCursor(page.Cursor); err != nil {
 99				return nil, "", err
100			}
101		}
102	
103		m.mu.RLock()
104		defer m.mu.RUnlock()
105		ids := m.byMerchant[merchantID]
106		if offset > len(ids) {
107			offset = len(ids)
108		}
109		out := make([]payment.Payment, 0, min(limit, len(ids)-offset))
110		nextOffset := -1
111		for i := offset; i < len(ids); i++ {
112			p := m.byID[ids[i]]
113			if status != "" && p.Status != status {
114				continue
115			}
116			if len(out) < limit {
117				out = append(out, p.Clone())
118				continue
119			}
120			nextOffset = i
121			break
122		}
123		next := ""
124		if nextOffset >= 0 {
125			next = encodeCursor(nextOffset)
126		}
127		return out, next, nil
128	}
129	
130	func encodeCursor(offset int) string {
131		return base64.RawURLEncoding.EncodeToString([]byte("o:" + strconv.Itoa(offset)))
132	}
133	
134	func decodeCursor(c string) (int, error) {
135		raw, err := base64.RawURLEncoding.DecodeString(c)
136		if err != nil {
137			return 0, fmt.Errorf("%w: %v", payment.ErrInvalidCursor, err)
138		}
139		n, ok := strings.CutPrefix(string(raw), "o:")
140		if !ok {
141			return 0, fmt.Errorf("%w: unexpected format", payment.ErrInvalidCursor)
142		}
143		off, err := strconv.Atoi(n)
144		if err != nil || off < 0 {
145			return 0, fmt.Errorf("%w: bad offset %q", payment.ErrInvalidCursor, n)
146		}
147		return off, nil
148	}

