142	func decodeJSON(r *http.Request, dst any) error {
143		dec := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes))
144		dec.DisallowUnknownFields()
145		if err := dec.Decode(dst); err != nil {
146			return fmt.Errorf("%w: malformed JSON body: %v", payment.ErrInvalidInput, err)
147		}
148		return nil
149	}
